const updatePosition = `-- name: UpdatePosition :one
UPDATE oikumenea.membership_positions SET
  title            = COALESCE($1, title),
  required_rank_id = COALESCE($2, required_rank_id),
  sort_order       = COALESCE($3, sort_order)
WHERE id = $4 AND deleted_at IS NULL
RETURNING id, unit_id, code, title, required_rank_id, status, sort_order, created_at, updated_at, deleted_at
`

type UpdatePositionParams struct {
	Title          pgtype.Text
	RequiredRankID pgtype.Text
	SortOrder      pgtype.Int4
	ID             string
}

// Partial update: a NULL narg leaves the value unchanged. `code` and unit_id are immutable; clearing
// required_rank_id to NULL via this path is an open seam (COALESCE cannot set NULL).
func (q *Queries) UpdatePosition(ctx context.Context, arg UpdatePositionParams) (OikumeneaMembershipPosition, error) {
	row := q.db.QueryRow(ctx, updatePosition,
		arg.Title,
		arg.RequiredRankID,
		arg.SortOrder,
		arg.ID,
	)
	var i OikumeneaMembershipPosition
	err := row.Scan(
		&i.ID,
		&i.UnitID,
		&i.Code,
		&i.Title,
		&i.RequiredRankID,
		&i.Status,
		&i.SortOrder,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

